use super::*;

pub(crate) fn handle(app: &tauri::AppHandle, env: &bsc_appchan::Envelope) -> Result<serde_json::Value, String> {
    match env.kind.as_str() {
        bsc_widget::KIND => {
            let req: bsc_widget::WidgetRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed widget request: {e}"))?;
            let res = crate::lan::apply(app, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_shot::KIND => {
            let req: bsc_shot::ShotRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed shot request: {e}"))?;
            let res = crate::shot::capture(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_fleet::KIND => {
            let req: bsc_fleet::FleetRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed fleet request: {e}"))?;
            let state = app.state::<crate::console::pty::PtyState>();
            let panes = crate::console::pty::pane_liveness(req.pane_ids, &state);
            serde_json::to_value(bsc_fleet::FleetResult { panes }).map_err(|e| e.to_string())
        }
        bsc_fleet::WAKE_KIND => {
            let req: bsc_fleet::WakeRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed fleet wake request: {e}"))?;
            let res = crate::fleet::wake::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_session::KIND => {
            let req: bsc_session::SessionListRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed session list request: {e}"))?;
            let res = crate::session::system::list(app, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_session::LIFECYCLE_KIND => {
            let req: bsc_session::LifecycleRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed session lifecycle request: {e}"))?;
            let res = crate::session::system::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_session::DELIVER_KIND => {
            let req: bsc_session::DeliverRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed session deliver request: {e}"))?;
            let res = crate::session::deliver::deliver(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_fleet::START_KIND => {
            let req: bsc_fleet::StartRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed fleet start request: {e}"))?;
            let res = crate::fleet::start::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_fleet::DIRECTOR_KIND => {
            let req: bsc_fleet::DirectorNewRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed fleet director request: {e}"))?;
            let res = crate::fleet::director_new::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_persona::WHATAMI_KIND => {
            let req: bsc_persona::WhatamiRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed persona whatami request: {e}"))?;
            let res = crate::session::persona_use::whatami(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_persona::USE_KIND => {
            let req: bsc_persona::UseRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed persona use request: {e}"))?;
            let res = crate::session::persona_use::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_navigate::KIND => {
            let req: bsc_navigate::NavRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed navigate request: {e}"))?;
            let res = crate::navigate::apply(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        bsc_debug::KIND => {
            let req: bsc_debug::DebugRequest = serde_json::from_value(env.payload.clone())
                .map_err(|e| format!("malformed debug request: {e}"))?;
            let res = crate::debug::inspect(app, &env.id, &req)?;
            serde_json::to_value(res).map_err(|e| e.to_string())
        }
        // A `bsc` newer than this app asking for a verb it doesn't have. Say so plainly — the caller
        // can't tell "unknown verb" from "the app is old" otherwise.
        other => Err(format!(
            "this app build has no handler for '{other}' — is `bsc` newer than the running app?"
        )),
    }
}
